using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;
using Homesteader.UI;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = GameObject.Find("HudRoot");
        if (hud == null) { result.Log("HudRoot missing"); return; }
        var bootstrap = hud.GetComponent<HudSceneBootstrap>();
        if (bootstrap == null) { result.Log("HudSceneBootstrap missing"); return; }
        var so = new SerializedObject(bootstrap);
        var prop = so.FindProperty("_enableKitOverlay");
        if (prop != null)
        {
            prop.boolValue = true;
            so.ApplyModifiedProperties();
            result.Log("Enabled _enableKitOverlay on HudSceneBootstrap.");
        }
        EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
        EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
        result.Log("Saved scene.");
    }
}
